/**
 * @param {number[][]} coins
 * @return {number}
 */
var maximumAmount = function(coins) {
    const m = coins.length;
    const n = coins[0].length;

    let max = -Infinity;

    const dfs = (row, col, seen) => {
        seen.push(coins[row][col]);

        if (row === m - 1 && col === n - 1) {
            const arr = [...seen].sort((a, b) => b - a);
            if (arr.length > 0 && arr[arr.length - 1] < 0) arr.pop();
            if (arr.length > 0 && arr[arr.length - 1] < 0) arr.pop();

            max = Math.max(max, arr.reduce((acc, el) => acc + el, 0));
        }

        if (row < m - 1) {
            dfs(row + 1, col, seen);
        }

        if (col < n - 1) {
            dfs(row, col + 1, seen);
        }

        seen.pop();
    };
    dfs(0, 0, []);

    return max;
};

/**
 * @param {number[][]} coins
 * @return {number}
 */
var maximumAmount = function(coins) {
    const m = coins.length;
    const n = coins[0].length;

    const dp = Array.from({ length: m }, () => Array.from({ length: n }, () => Array(3).fill(0)));
    dp[0][0][0] = coins[0][0];
    dp[0][0][1] = coins[0][0] < 0 ? 0 : coins[0][0];
    dp[0][0][2] = coins[0][0] < 0 ? 0 : coins[0][0];

    for (let row = 1; row < m; row++) {
        const val = coins[row][0];

        dp[row][0][0] = val + dp[row - 1][0][0];
        dp[row][0][1] = val + dp[row - 1][0][1];
        dp[row][0][2] = val + dp[row - 1][0][2];

        if (val < 0) {
            dp[row][0][1] = Math.max(dp[row][0][1], dp[row - 1][0][0]);
            dp[row][0][2] = Math.max(dp[row][0][2], dp[row - 1][0][1]);
        }
    }

    for (let col = 1; col < n; col++) {
        const val = coins[0][col];

        dp[0][col][0] = val + dp[0][col - 1][0];
        dp[0][col][1] = val + dp[0][col - 1][1];
        dp[0][col][2] = val + dp[0][col - 1][2];

        if (val < 0) {
            dp[0][col][1] = Math.max(dp[0][col][1], dp[0][col - 1][0]);
            dp[0][col][2] = Math.max(dp[0][col][2], dp[0][col - 1][1]);
        }
    }

    //console.log(dp);

    for (let row = 1; row < m; row++) {
        for (let col = 1; col < n; col++) {
            const val = coins[row][col];

            dp[row][col][0] = val + Math.max(dp[row - 1][col][0], dp[row][col - 1][0]);
            dp[row][col][1] = val + Math.max(dp[row - 1][col][1], dp[row][col - 1][1]);
            dp[row][col][2] = val + Math.max(dp[row - 1][col][2], dp[row][col - 1][2]);

            if (val < 0) {
                dp[row][col][1] = Math.max(
                    dp[row][col][1],
                    dp[row - 1][col][0],
                    dp[row][col - 1][0],
                );
                dp[row][col][2] = Math.max(
                    dp[row][col][2],
                    dp[row - 1][col][1],
                    dp[row][col - 1][1],
                );
            }
        }
    }

    //console.log(dp);

    return Math.max(...dp[m - 1][n - 1]);
};
